css:
.d-dl{display:flex;flex-direction:column;align-items:flex-start;gap:8px;width:260px}
.d-dl-art{display:block;width:260px;height:96px;overflow:visible}
.d-dl-sketch,.d-dl-ink{fill:none;stroke-width:1;stroke-linecap:round;stroke-linejoin:round}
.d-dl-sketch{stroke:var(--faint);stroke-dasharray:2 4}
.d-dl-ink{stroke:var(--ink);stroke-dasharray:271;stroke-dashoffset:0}
.d-dl.is-run .d-dl-ink{animation:d-svg-draw-line-ink 900ms cubic-bezier(.2,.75,.25,1) both}
@keyframes d-svg-draw-line-ink{from{stroke-dashoffset:271}to{stroke-dashoffset:0}}
.d-dl-btn{font-family:var(--font-mono);font-size:var(--fs-11);letter-spacing:var(--tracking-mono-label);padding:8px 12px;border:1px solid var(--line);border-radius:6px;background:var(--paper);color:var(--muted);cursor:pointer;transition:border-color 120ms cubic-bezier(.2,.75,.25,1),color 120ms cubic-bezier(.2,.75,.25,1)}
.d-dl-btn:hover{border-color:var(--ink);color:var(--ink)}
.d-dl-btn:focus-visible{outline:1px solid var(--ink);outline-offset:2px}

init:
root => {
    const box = root.querySelector('.d-dl'), btn = box.querySelector('.d-dl-btn');
    const run = () => { box.classList.remove('is-run'); void box.offsetWidth; box.classList.add('is-run'); };
    btn.onclick = run;
    run();
  }
